<script lang="ts">
  /**
   * "Erro médio por casa" as a dot-and-interval chart, with a bar alternative.
   *
   * Deliberately not a smoothed curve: there are four elections, not a
   * continuum, so an interpolated line would draw observations that do not
   * exist. Raw and shrunk means are shown as two distinct marks on the same
   * row so the reader can see how much a thin history was pulled toward the
   * average.
   */
  import { formatNumber } from '../lib/format';
  import type { HouseSummaryRow } from '../lib/types';

  export let houses: HouseSummaryRow[];
  export let grandMean: number | null = null;
  export let kind: 'dots' | 'bars' = 'dots';
  export let metric: 'mae' | 'margin' = 'mae';

  const ROW_HEIGHT = 34;
  const LEFT = 168;
  const RIGHT = 700;

  $: valueOf = (house: HouseSummaryRow) =>
    metric === 'mae' ? house.mae_raw : house.margin_error_raw;
  $: shrunkOf = (house: HouseSummaryRow) =>
    metric === 'mae' ? house.mae_shrunk : house.margin_error_shrunk;

  $: rows = houses
    .filter((house) => valueOf(house) !== null)
    .slice()
    .sort((a, b) => (valueOf(a) ?? 0) - (valueOf(b) ?? 0));

  $: values = rows.flatMap((house) => {
    const interval = metric === 'mae' ? house.mae_observation_level : house.margin_error_interval;
    return [
      valueOf(house) ?? 0,
      shrunkOf(house) ?? 0,
      interval?.ci95_low ?? valueOf(house) ?? 0,
      interval?.ci95_high ?? valueOf(house) ?? 0,
    ];
  });
  $: lower = metric === 'mae' ? 0 : Math.min(-1, Math.floor(Math.min(...values, 0)));
  $: upper = Math.max(1, Math.ceil(Math.max(...values, 1)));
  $: ticks = Array.from({ length: 5 }, (_, index) => lower + ((upper - lower) / 4) * index);
  $: height = rows.length * ROW_HEIGHT + 56;

  function xFor(value: number): number {
    const clamped = Math.min(upper, Math.max(lower, value));
    return LEFT + ((clamped - lower) / (upper - lower)) * (RIGHT - LEFT);
  }

  function intervalOf(house: HouseSummaryRow) {
    return metric === 'mae' ? house.mae_observation_level : house.margin_error_interval;
  }

  const unit = 'p.p.';
</script>

<div class="house-error-chart">
  {#if rows.length === 0}
    <p class="chart-no-data">Nenhuma casa com métrica disponível nesta janela.</p>
  {:else}
    <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
    <div class="house-error-scroll" tabindex="0" role="region" aria-label="Gráfico de erro por casa">
      <svg viewBox={`0 0 760 ${height}`} role="img" aria-labelledby="house-error-title house-error-desc">
        <title id="house-error-title">
          {metric === 'mae' ? 'Erro absoluto médio por casa' : 'Erro de margem assinado por casa'}
        </title>
        <desc id="house-error-desc">
          {rows.length} casas ordenadas do menor para o maior erro. Cada linha traz a média bruta,
          a média encolhida e o intervalo de 95% quando estimável.
          {metric === 'margin' ? 'Valores positivos indicam disputa mostrada mais folgada do que foi.' : 'Menor é melhor.'}
        </desc>

        {#each ticks as tick}
          <line class="chart-gridline" x1={xFor(tick)} x2={xFor(tick)} y1="20" y2={height - 30} />
          <text class="chart-axis-label" x={xFor(tick)} y={height - 12} text-anchor="middle">{formatNumber(tick)}</text>
        {/each}
        {#if grandMean !== null && metric === 'mae'}
          <line class="chart-reference" x1={xFor(grandMean)} x2={xFor(grandMean)} y1="20" y2={height - 30} />
          <text class="chart-reference-label" x={xFor(grandMean)} y="14" text-anchor="middle">média geral {formatNumber(grandMean)}</text>
        {/if}
        {#if metric === 'margin'}
          <line class="chart-zero" x1={xFor(0)} x2={xFor(0)} y1="20" y2={height - 30} />
        {/if}

        {#each rows as house, index}
          {@const y = 34 + index * ROW_HEIGHT}
          {@const raw = valueOf(house) ?? 0}
          {@const shrunk = shrunkOf(house) ?? 0}
          {@const band = intervalOf(house)}
          <text class="house-error-label" x={LEFT - 12} y={y + 4} text-anchor="end">{house.house_name}</text>
          <text class="house-error-meta" x={LEFT - 12} y={y + 16} text-anchor="end">
            {house.n_cells} célula(s) · n={house.n_observations}
          </text>
          {#if kind === 'bars'}
            <rect
              class="house-error-bar"
              x={metric === 'margin' ? Math.min(xFor(0), xFor(raw)) : xFor(lower)}
              y={y - 8}
              width={Math.max(2, Math.abs(xFor(raw) - xFor(metric === 'margin' ? 0 : lower)))}
              height="16"
              tabindex="0"
              role="graphics-symbol"
              aria-label={`${house.house_name}: bruto ${formatNumber(raw)} ${unit}, encolhido ${formatNumber(shrunk)} ${unit}, ${house.n_observations} pesquisas em ${house.n_cells} célula(s)`}
            />
          {:else}
            {#if band?.ci95_low !== null && band?.ci95_low !== undefined && band?.ci95_high !== null && band?.ci95_high !== undefined}
              <line class="house-error-interval" x1={xFor(band.ci95_low)} x2={xFor(band.ci95_high)} y1={y} y2={y} />
              <line class="house-error-cap" x1={xFor(band.ci95_low)} x2={xFor(band.ci95_low)} y1={y - 5} y2={y + 5} />
              <line class="house-error-cap" x1={xFor(band.ci95_high)} x2={xFor(band.ci95_high)} y1={y - 5} y2={y + 5} />
            {/if}
            <circle
              class="house-error-raw"
              cx={xFor(raw)}
              cy={y}
              r="6"
              tabindex="0"
              role="graphics-symbol"
              aria-label={`${house.house_name}: média bruta ${formatNumber(raw)} ${unit} em ${house.n_observations} pesquisas de ${house.n_cells} célula(s)`}
            />
            <rect
              class="house-error-shrunk"
              x={xFor(shrunk) - 4}
              y={y - 4}
              width="8"
              height="8"
              tabindex="0"
              role="graphics-symbol"
              aria-label={`${house.house_name}: média encolhida ${formatNumber(shrunk)} ${unit}, peso na própria casa ${house.mae_shrinkage_weight === null ? 'não estimável' : formatNumber((house.mae_shrinkage_weight ?? 0) * 100) + '%'}`}
            />
          {/if}
          {#if house.status !== 'scored'}
            <text class="house-error-flag" x={RIGHT + 6} y={y + 4}>dados finos</text>
          {/if}
        {/each}
      </svg>
    </div>
    <div class="chart-key" aria-hidden="true">
      {#if kind === 'dots'}
        <span><i class="key-raw"></i>média bruta</span>
        <span><i class="key-shrunk"></i>média encolhida</span>
        <span><i class="key-interval"></i>IC 95%</span>
      {:else}
        <span><i class="key-bar"></i>média bruta</span>
      {/if}
    </div>
  {/if}
</div>
