<script lang="ts">
  import DataTable from '../components/DataTable.svelte';
  import { candidateMedia } from '../lib/candidateMedia';
  import { formatDate, formatNumber, formatPublishedNumber } from '../lib/format';
  import type { HistoryBundle } from '../lib/types';

  export let history: HistoryBundle;

  const strengthCopy: Record<string, { label: string; blurb: string }> = {
    insuficiente: {
      label: 'Insuficiente',
      blurb: 'Não há duas medições comparáveis da mesma casa. Não é possível falar em movimento.',
    },
    fraco: {
      label: 'Fraco',
      blurb: 'Uma casa só, ou direções divergentes, ou variação dentro do ruído amostral.',
    },
    moderado: {
      label: 'Moderado',
      blurb: 'Pelo menos duas casas na mesma direção, acima do erro amostral típico.',
    },
    forte: {
      label: 'Forte',
      blurb: 'Três ou mais casas na mesma direção, acima de duas vezes o erro amostral.',
    },
  };

  $: signal = history.signal;
  $: context = signal.historical_context_at_this_distance as Record<string, unknown>;
  $: contextAvailable = context?.status === 'available';
</script>

<section class="page-stack" aria-labelledby="signal-title">
  <header class="page-hero compact-hero">
    <p class="eyebrow">Diagnóstico de tendência · {signal.days_to_election} dias para o 1º turno</p>
    <h1 id="signal-title">Alguma candidatura está realmente melhorando?</h1>
    <p>
      Esta página não é o agregador. Ela responde apenas se a variação recente nos números
      publicados é sinal ou ruído — e recusa a resposta quando os dados não permitem.
    </p>
  </header>

  {#if !signal.gate_satisfied}
    <div class="alert-inline" role="status">
      <strong>O agregador segue bloqueado.</strong> {signal.gate_message}
      Esta página descreve medições, não previsões.
    </div>
  {/if}

  <section class="content-section" aria-labelledby="ladder-title">
    <div class="section-heading">
      <div>
        <p class="eyebrow">Regra declarada antes de olhar os dados</p>
        <h2 id="ladder-title">Escada de força de evidência</h2>
      </div>
    </div>
    <div class="ladder-grid">
      {#each signal.strength_ladder.levels as level}
        <article class={`ladder-step level-${level}`}>
          <h3>{strengthCopy[level]?.label ?? level}</h3>
          <p>{strengthCopy[level]?.blurb ?? ''}</p>
          <span class="ladder-count">{signal.summary.by_strength[level] ?? 0} candidatura(s)</span>
        </article>
      {/each}
    </div>
    <p class="inline-note">{signal.comparability_rule}</p>
  </section>

  <section class="content-section" aria-labelledby="signals-title">
    <div class="section-heading">
      <div>
        <p class="eyebrow">Por candidatura</p>
        <h2 id="signals-title">Movimento medido dentro de cada casa</h2>
      </div>
      <p>Casas diferentes nunca são ligadas como série temporal.</p>
    </div>

    {#each signal.signals as row}
      <article class={`signal-card strength-${row.evidence_strength}`} id={row.candidate_id}>
        <header>
          <h3>{candidateMedia(row.candidate_id, row.candidate_label).displayName}</h3>
          <span class={`signal-badge strength-${row.evidence_strength}`}>
            {strengthCopy[row.evidence_strength]?.label ?? row.evidence_strength}
          </span>
        </header>
        <p class="signal-explanation">{row.explanation}</p>
        <dl class="signal-metrics">
          <div><dt>Casas na janela</dt><dd>{row.houses_in_window}</dd></div>
          <div><dt>Casas com série comparável</dt><dd>{row.houses_with_comparable_series}</dd></div>
          <div>
            <dt>Variação mediana</dt>
            <dd>{row.median_delta_pp === null ? 'não calculável' : `${formatNumber(row.median_delta_pp)} p.p.`}</dd>
          </div>
          <div>
            <dt>Dispersão entre casas</dt>
            <dd>{row.between_house_sd_pp === null ? '—' : `${formatNumber(row.between_house_sd_pp)} p.p.`}</dd>
          </div>
        </dl>

        {#if row.observations.length}
          <details>
            <summary>Ver as {row.observations.length} medições usadas</summary>
            <DataTable label={`Medições de ${row.candidate_label}`}>
              <table>
                <thead><tr><th>Casa</th><th>Campo até</th><th>Publicação</th><th class="num">%</th><th class="num">Amostra</th><th>Modo</th><th>Registro</th></tr></thead>
                <tbody>
                  {#each row.observations as observation}
                    <tr>
                      <th scope="row">{observation.institute}</th>
                      <td>{formatDate(observation.field_end)}</td>
                      <td>{formatDate(observation.published_at)}</td>
                      <td class="num">{formatPublishedNumber(observation.pct)}%</td>
                      <td class="num">{observation.sample_size?.toLocaleString('pt-BR') ?? '—'}</td>
                      <td>{observation.mode}</td>
                      <td>{observation.registration_no}</td>
                    </tr>
                  {/each}
                </tbody>
              </table>
            </DataTable>
            {#if row.houses_with_single_measurement.length}
              <p class="inline-note">
                Casas com uma única medição nesta janela: {row.houses_with_single_measurement.join(', ')}.
                Uma medição não produz variação.
              </p>
            {/if}
          </details>
        {/if}
        <p class="small muted">{row.not_a_forecast}</p>
      </article>
    {/each}
  </section>

  <section class="content-section" aria-labelledby="context-title">
    <div class="section-heading">
      <div>
        <p class="eyebrow">Comparação com ciclos passados</p>
        <h2 id="context-title">Como era a esta distância da eleição</h2>
      </div>
    </div>
    {#if contextAvailable}
      <p>
        A {String(context.days_to_election)} ± {String(context.tolerance_days)} dias da eleição,
        {String(context.n_observations)} pesquisas históricas tiveram erro de margem com mediana
        <strong>{formatNumber(Number(context.median_margin_error_pp))} p.p.</strong>
      </p>
      <DataTable label="Erro histórico a esta distância da eleição">
        <table>
          <thead><tr><th>Eleição</th><th class="num">Pesquisas</th><th class="num">Casas</th><th class="num">Erro de margem (mediana)</th><th class="num">MAE</th></tr></thead>
          <tbody>
            {#each (context.per_election as Array<Record<string, number | string>>) ?? [] as row}
              <tr>
                <th scope="row">{row.election}</th>
                <td class="num">{row.n}</td>
                <td class="num">{row.houses}</td>
                <td class="num">{formatNumber(Number(row.median_margin_error_pp))}</td>
                <td class="num">{formatNumber(Number(row.mae))}</td>
              </tr>
            {/each}
          </tbody>
        </table>
      </DataTable>
      <p class="inline-note">{String(context.reading)}</p>
    {:else}
      <p class="inline-note">{String(context.reason ?? 'Contexto histórico indisponível para esta distância.')}</p>
    {/if}
  </section>
</section>
