<script lang="ts">
  /**
   * Desempenho ao longo de 2026: publicado × corrigido, ponto a ponto.
   *
   * Regra dura preservada no desenho: **a linha só liga pontos da mesma casa**.
   * Ligar PoderData com Nexus mediria diferença entre casas, não movimento no
   * tempo. Pontos de casas distintas aparecem soltos, com a casa no rótulo.
   *
   * Cada medição entra duas vezes: o que a casa publicou (círculo vazado,
   * linha tracejada) e o valor corrigido pela lente daquela casa (círculo
   * cheio, linha sólida). A distância vertical entre os dois é o ajuste.
   */
  import DataTable from './DataTable.svelte';
  import { formatDate, formatNumber, formatSigned } from '../lib/format';
  import type { ScenarioTimeline, TimelinePoint } from '../lib/types';

  export let timeline: ScenarioTimeline;

  const COLORS = ['#1f65d6', '#c1652c', '#14806b', '#7c5cc4', '#a3801a', '#2f7eaa'];
  const PLOT = { left: 54, right: 720, top: 22, bottom: 250 };

  let selected: string[] = [];
  let hovered: { point: TimelinePoint; label: string; published: number; corrected: number; x: number; y: number } | null = null;

  $: allSeries = timeline.series;
  // Por padrão, as candidaturas presentes em mais medições — as que de fato
  // têm série. O usuário pode ligar/desligar qualquer uma.
  $: if (selected.length === 0 && allSeries.length) {
    selected = allSeries.slice(0, 3).map((row) => row.series_key);
  }
  $: colorOf = (key: string) => COLORS[allSeries.findIndex((row) => row.series_key === key) % COLORS.length];

  $: points = [...timeline.points]
    .filter((point) => point.field_end)
    .sort((a, b) => String(a.field_end).localeCompare(String(b.field_end)));

  $: times = points.map((point) => new Date(`${point.field_end}T12:00:00`).getTime());
  $: minTime = times.length ? Math.min(...times) : 0;
  $: maxTime = times.length ? Math.max(...times) : 1;

  $: shownValues = points.flatMap((point) =>
    point.candidates
      .filter((row) => selected.includes(row.series_key))
      .flatMap((row) => [row.published_valid_pct, row.corrected_valid_pct]),
  );
  $: maxValue = shownValues.length ? Math.max(...shownValues) : 50;
  $: yMax = Math.max(10, Math.ceil((maxValue + 4) / 10) * 10);
  $: yTicks = Array.from({ length: 5 }, (_, index) => (yMax / 4) * index);

  function xFor(fieldEnd: string | null): number {
    if (!fieldEnd) return PLOT.left;
    const time = new Date(`${fieldEnd}T12:00:00`).getTime();
    if (maxTime === minTime) return (PLOT.left + PLOT.right) / 2;
    return PLOT.left + ((time - minTime) / (maxTime - minTime)) * (PLOT.right - PLOT.left);
  }

  function yFor(value: number): number {
    const clamped = Math.min(yMax, Math.max(0, value));
    return PLOT.bottom - (clamped / yMax) * (PLOT.bottom - PLOT.top);
  }

  /** One polyline per (candidate, house): never across houses. */
  $: lines = selected.flatMap((key) => {
    const byHouse = new Map<string, Array<{ point: TimelinePoint; published: number; corrected: number }>>();
    points.forEach((point) => {
      const row = point.candidates.find((item) => item.series_key === key);
      if (!row) return;
      const list = byHouse.get(point.house_id) ?? [];
      list.push({ point, published: row.published_valid_pct, corrected: row.corrected_valid_pct });
      byHouse.set(point.house_id, list);
    });
    return [...byHouse.entries()]
      .filter(([, list]) => list.length >= 2)
      .map(([houseId, list]) => ({
        key,
        houseId,
        houseName: list[0].point.house_name,
        color: colorOf(key),
        published: list.map((item) => `${xFor(item.point.field_end)},${yFor(item.published)}`).join(' '),
        corrected: list.map((item) => `${xFor(item.point.field_end)},${yFor(item.corrected)}`).join(' '),
      }));
  });

  $: marks = points.flatMap((point) =>
    point.candidates
      .filter((row) => selected.includes(row.series_key))
      .map((row) => ({ point, row, color: colorOf(row.series_key) })),
  );

  function toggle(key: string): void {
    if (selected.includes(key)) {
      if (selected.length > 1) selected = selected.filter((item) => item !== key);
    } else {
      selected = [...selected, key];
    }
  }

  function describe(point: TimelinePoint, label: string, published: number, corrected: number): string {
    return (
      `${label} · ${point.house_name} · campo até ${formatDate(String(point.field_end))} · ` +
      `publicado ${formatNumber(published)}%, corrigido ${formatNumber(corrected)}% ` +
      `(${formatSigned(corrected - published)} p.p.)` +
      (point.pre_registration ? ' · cenário pré-registro' : '')
    );
  }
</script>

<section class="scenario-timeline" aria-labelledby="timeline-title">
  <header class="section-title-row compact">
    <div>
      <p class="mini-label">Desempenho ao longo de 2026</p>
      <h2 id="timeline-title">Como cada medição ficou, antes e depois da correção</h2>
      <p>
        {timeline.n_points} medições aceitas de {timeline.houses.length} casas ({timeline.houses.join(', ')}).
        {timeline.note}
      </p>
    </div>
  </header>

  <div class="timeline-legend" role="group" aria-label="Candidaturas exibidas no gráfico">
    {#each allSeries as row}
      <button
        type="button"
        class:muted={!selected.includes(row.series_key)}
        aria-pressed={selected.includes(row.series_key)}
        style={`--series-color:${colorOf(row.series_key)}`}
        onclick={() => toggle(row.series_key)}
      ><span aria-hidden="true"></span>{row.label}<small>{row.points} medições</small></button>
    {/each}
  </div>

  <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
  <div class="timeline-wrap" tabindex="0" role="region" aria-label="Gráfico do cenário corrigido ao longo do tempo">
    {#if points.length}
      <svg viewBox="0 0 760 300" role="img" aria-labelledby="timeline-svg-title timeline-svg-desc">
        <title id="timeline-svg-title">Publicado e corrigido por medição, ao longo de 2026</title>
        <desc id="timeline-svg-desc">
          {points.length} medições de {timeline.houses.length} casas. Linha sólida é o valor corrigido,
          tracejada é o publicado; ambas ligam apenas medições da mesma casa. Os valores estão na tabela abaixo.
        </desc>

        {#each yTicks as tick}
          <line class="chart-gridline" x1={PLOT.left - 8} x2={PLOT.right} y1={yFor(tick)} y2={yFor(tick)} />
          <text class="chart-axis-label" x={PLOT.left - 14} y={yFor(tick) + 4} text-anchor="end">{Math.round(tick)}%</text>
        {/each}
        <line class="chart-axis" x1={PLOT.left - 8} x2={PLOT.right} y1={PLOT.bottom} y2={PLOT.bottom} />

        {#each lines as line}
          <polyline class="timeline-line published" points={line.published} stroke={line.color} fill="none" />
          <polyline class="timeline-line corrected" points={line.corrected} stroke={line.color} fill="none" />
        {/each}

        {#each marks as mark}
          {@const x = xFor(mark.point.field_end)}
          <line class="timeline-link" x1={x} x2={x} y1={yFor(mark.row.published_valid_pct)} y2={yFor(mark.row.corrected_valid_pct)} stroke={mark.color} />
          <circle
            class="timeline-published"
            cx={x}
            cy={yFor(mark.row.published_valid_pct)}
            r="4"
            stroke={mark.color}
            fill="#fff"
            tabindex="0"
            role="graphics-symbol"
            aria-label={describe(mark.point, mark.row.label, mark.row.published_valid_pct, mark.row.corrected_valid_pct)}
            onmouseenter={() => (hovered = { point: mark.point, label: mark.row.label, published: mark.row.published_valid_pct, corrected: mark.row.corrected_valid_pct, x, y: yFor(mark.row.published_valid_pct) })}
            onmouseleave={() => (hovered = null)}
            onfocus={() => (hovered = { point: mark.point, label: mark.row.label, published: mark.row.published_valid_pct, corrected: mark.row.corrected_valid_pct, x, y: yFor(mark.row.published_valid_pct) })}
            onblur={() => (hovered = null)}
          />
          <circle
            class="timeline-corrected"
            cx={x}
            cy={yFor(mark.row.corrected_valid_pct)}
            r="5.5"
            fill={mark.color}
            tabindex="0"
            role="graphics-symbol"
            aria-label={describe(mark.point, mark.row.label, mark.row.published_valid_pct, mark.row.corrected_valid_pct)}
            onmouseenter={() => (hovered = { point: mark.point, label: mark.row.label, published: mark.row.published_valid_pct, corrected: mark.row.corrected_valid_pct, x, y: yFor(mark.row.corrected_valid_pct) })}
            onmouseleave={() => (hovered = null)}
            onfocus={() => (hovered = { point: mark.point, label: mark.row.label, published: mark.row.published_valid_pct, corrected: mark.row.corrected_valid_pct, x, y: yFor(mark.row.corrected_valid_pct) })}
            onblur={() => (hovered = null)}
          />
        {/each}

        {#each points as point, index}
          {@const x = xFor(point.field_end)}
          <line class="date-tick" x1={x} x2={x} y1={PLOT.bottom} y2={PLOT.bottom + 6} />
          <text class="chart-date" x={x} y={PLOT.bottom + 22} text-anchor="middle">{formatDate(String(point.field_end))}</text>
          <text class="chart-house" x={x} y={PLOT.bottom + 38} text-anchor="middle">{point.house_name}</text>
          {#if point.pre_registration}
            <text class="chart-regime" x={x} y={PLOT.bottom + 52} text-anchor="middle">pré-registro</text>
          {/if}
        {/each}
      </svg>
      {#if hovered}
        <div class="chart-tooltip" style={`left:${(hovered.x / 760) * 100}%; top:${(hovered.y / 300) * 100}%`} role="status">
          <strong>{hovered.label}</strong>
          <span>{hovered.point.house_name} · campo até {formatDate(String(hovered.point.field_end))}</span>
          <small>publicado {formatNumber(hovered.published)}% → corrigido {formatNumber(hovered.corrected)}% ({formatSigned(hovered.corrected - hovered.published)} p.p.)</small>
          <small>{hovered.point.registration_no ?? 'sem registro'}{hovered.point.pre_registration ? ' · pré-registro' : ''}</small>
        </div>
      {/if}
    {:else}
      <p class="chart-no-data">Nenhuma medição 2026 aceita ainda.</p>
    {/if}
  </div>

  <p class="chart-key timeline-key" aria-hidden="true">
    <span><i class="key-corrected"></i>corrigido (linha sólida)</span>
    <span><i class="key-published"></i>publicado (linha tracejada)</span>
    <span>linhas ligam só medições da mesma casa</span>
  </p>

  <details class="timeline-history">
    <summary>Histórico completo dos dados ({points.length} medições)</summary>
    <DataTable label="Histórico das medições 2026, publicado e corrigido">
      <table>
        <thead>
          <tr>
            <th scope="col">Campo até</th><th scope="col">Casa</th><th scope="col">Registro</th>
            <th scope="col">Candidatura</th><th scope="col" class="num">Publicado</th>
            <th scope="col" class="num">Corrigido</th><th scope="col" class="num">Ajuste</th><th scope="col">Regime</th>
          </tr>
        </thead>
        <tbody>
          {#each points as point}
            {#each point.candidates.filter((row) => selected.includes(row.series_key)) as row}
              <tr>
                <th scope="row">{formatDate(String(point.field_end))}</th>
                <td>{point.house_name}</td>
                <td>{point.registration_no ?? '—'}</td>
                <td>{row.label}</td>
                <td class="num">{formatNumber(row.published_valid_pct)}%</td>
                <td class="num">{formatNumber(row.corrected_valid_pct)}%</td>
                <td class="num">{row.adjusted ? formatSigned(row.adjustment_pp) : 'sem ajuste'}</td>
                <td>{point.pre_registration ? 'pré-registro' : 'pós-registro'}</td>
              </tr>
            {/each}
          {/each}
        </tbody>
      </table>
    </DataTable>
    <p class="inline-note">
      Medição <strong>pré-registro</strong> é anterior ao prazo de registro de candidaturas (15/08/2026):
      entra como corpus histórico e nunca no gate vivo, no sinal ou no consenso. Valores em votos válidos.
    </p>
  </details>
</section>
