function fallbackInitials(label: string): string {
  return label
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0] ?? '')
    .join('')
    .toLocaleUpperCase('pt-BR');
}

export function candidateMedia(candidateId: string, fallbackLabel: string): CandidateMedia {
  return media[candidateId] ?? {
    displayName: fallbackLabel,
    initials: fallbackInitials(fallbackLabel),
    asset: null,
    alt: `Foto oficial indisponível; iniciais de ${fallbackLabel}`,
    sourceLabel: null,
    sourcePage: null,
  };
}
