<script lang="ts">
  import CandidatePortrait from '../components/CandidatePortrait.svelte';
  import { candidateMedia } from '../lib/candidateMedia';
  import { formatDate, formatNumber, formatPublishedNumber } from '../lib/format';
  import type { LivePoll, OperationsPayload } from '../lib/types';

  export let operations: OperationsPayload;
  export let initialHouse = '';

  let selectedHouse = initialHouse;
  $: filtered = operations.live_polls.filter((poll) => !selectedHouse || poll.institute_id === selectedHouse);

  function displayName(candidateId: string, label: string): string {
    return candidateMedia(candidateId, label).displayName;
  }
</script>

<section class="page-stack live-polls-page" aria-labelledby="polls-title">
  <header class="live-page-hero">
    <div><p class="mini-label">Cobertura nacional validada</p><h1 id="polls-title">Pesquisas 2026</h1><p>Cada observação mantém registro, campo, amostra, método e fonte. Com duas pesquisas, os resultados são publicados separadamente e ainda não formam consenso.</p></div>
    <span class="coverage-count"><strong>{operations.live_coverage.polls}</strong> pesquisas · <strong>{operations.live_coverage.houses}</strong> casas</span>
  </header>

  <div class="poll-page-toolbar">
    <label for="poll-house"><span>Instituto</span><select id="poll-house" bind:value={selectedHouse}><option value="">Todos</option>{#each operations.live_coverage.house_details as house}<option value={house.id}>{house.name}</option>{/each}</select></label>
    <p aria-live="polite">{filtered.length} {filtered.length === 1 ? 'pesquisa exibida' : 'pesquisas exibidas'}</p>
    <a href="/data/latest/operations.json" download>Baixar contrato vivo</a>
  </div>

  {#if !operations.live_coverage.gate_satisfied}
    <aside class="inline-gate" role="note"><span aria-hidden="true">—</span><div><strong>Consenso e chances indisponíveis</strong><p>Gate atual: {operations.live_coverage.polls}/{operations.live_coverage.min_polls} pesquisas e {operations.live_coverage.houses}/{operations.live_coverage.min_houses} casas.</p></div></aside>
  {/if}

  <div class="live-poll-list">
    {#each filtered as poll, index}
      <article class="live-poll-detail" id={poll.registration_no}>
        <header>
          <div><p class="mini-label">{index === 0 && !selectedHouse ? 'Publicação mais recente' : 'Fonte primária validada'}</p><h2>{poll.institute}</h2><p>Publicada em {formatDate(poll.published_at)} · campo {formatDate(poll.field_start)}–{formatDate(poll.field_end)}</p></div>
          <span class="source-tier">Fonte {poll.source_tier}</span>
        </header>
        <dl class="poll-facts">
          <div><dt>Registro TSE</dt><dd>{poll.registration_no}</dd></div>
          <div><dt>Amostra</dt><dd>{poll.sample_size.toLocaleString('pt-BR')}</dd></div>
          <div><dt>Modo</dt><dd>{poll.mode}</dd></div>
          <div><dt>Margem / confiança</dt><dd>±{formatNumber(poll.margin_of_error)} p.p. · {formatNumber(poll.confidence_level)}%</dd></div>
        </dl>
        <div class="poll-result-list" role="list" aria-label={`Resultados publicados por ${poll.institute}`}>
          {#each poll.values as value}
            <div role="listitem">
              <CandidatePortrait candidateId={value.candidate_id} label={value.label} size="small" />
              <span><strong>{displayName(value.candidate_id, value.label)}</strong><small>{value.party} · {value.number}</small></span>
              <strong data-value={value.pct} data-kind="Publicado" data-run-id={operations.run_id} data-evidence={value.evidence_id}>{formatPublishedNumber(value.pct)}%</strong>
            </div>
          {/each}
        </div>
        <div class="poll-residuals"><span>Branco/nulo <strong>{formatNumber(poll.blank_null_pct ?? 0)}%</strong></span><span>NS/NR <strong>{formatNumber(poll.undecided_pct ?? 0)}%</strong></span><span>Soma publicada <strong>{formatNumber(poll.sum_pct)}%</strong></span></div>
        <footer><span><code>{poll.evidence_id}</code></span>{#if poll.source_url}<a href={poll.source_url} target="_blank" rel="noreferrer">Abrir fonte original <span class="sr-only">de {poll.institute} em nova aba</span>↗</a>{/if}</footer>
      </article>
    {/each}
  </div>
</section>
