<script lang="ts">
  /**
   * The story of the latest poll: who went up or down against the last
   * comparable measurement — and, when no comparable one exists, that fact,
   * stated instead of faked with a different house.
   */
  import { candidateMedia } from '../lib/candidateMedia';
  import { formatDate, formatNumber, formatSigned } from '../lib/format';
  import type { CurrentSignalPayload, ScenarioPayload } from '../lib/types';

  export let signal: CurrentSignalPayload;
  export let scenario: ScenarioPayload | null = null;

  $: comparison = signal.latest_poll_comparison ?? null;
  $: latest = comparison?.latest ?? null;
  $: rows = comparison?.candidates ?? [];
  $: teaser = scenario?.aggregate.candidates.slice(0, 2) ?? [];

  function displayName(id: string, label: string): string {
    return candidateMedia(id, label).displayName;
  }
</script>

{#if comparison && latest}
  <section class="latest-story" aria-labelledby="latest-story-title" id="ultima-pesquisa">
    <header class="section-title-row compact">
      <div>
        <p class="mini-label">Última pesquisa · {latest.institute} · {latest.registration_no}</p>
        <h2 id="latest-story-title">O que mudou na última pesquisa</h2>
        <p>Campo até {formatDate(latest.reference_date)}, publicada em {formatDate(latest.published_at)}.</p>
      </div>
    </header>

    {#if comparison.status === 'compared' && comparison.previous}
      <p class="story-summary">{comparison.summary}</p>
      <p class="story-basis">
        Comparação com a medição anterior da mesma casa e mesmo cenário
        ({comparison.previous.registration_no}, campo até {formatDate(comparison.previous.reference_date)}, {comparison.days_between} dias antes).
      </p>
      <ul class="story-list">
        {#each rows.slice(0, 6) as row}
          <li class:up={row.direction === 'alta'} class:down={row.direction === 'baixa'}>
            <span class="dir {row.direction === 'alta' ? 'dir-up' : row.direction === 'baixa' ? 'dir-down' : 'dir-flat'}" aria-hidden="true">{row.direction === 'alta' ? '▲' : row.direction === 'baixa' ? '▼' : '＝'}</span>
            <strong>{displayName(row.candidate_id, row.label)}</strong>
            <span>{formatNumber(row.previous_pct)}% → {formatNumber(row.latest_pct)}% ({formatSigned(row.delta_pp)} p.p.{row.beyond_sampling_noise ? ', fora do ruído amostral' : ', dentro do ruído amostral'})</span>
          </li>
        {/each}
      </ul>
    {:else}
      <div class="story-empty" role="note">
        <strong>Sem comparação legítima.</strong>
        <p>{comparison.reason}</p>
        <p class="small muted">{comparison.comparability_rule}</p>
      </div>
    {/if}

    {#if scenario && teaser.length}
      <aside class="story-scenario" aria-label="Cenário exploratório de correção">
        <p class="mini-label">Cenário exploratório · não é o consenso</p>
        <p>
          E se corrigirmos pelo erro histórico das casas?
          {#each teaser as row, index}
            {index ? ' · ' : ' '}<strong>{displayName(row.candidate_id, row.label)} {formatNumber(row.corrected_valid_mean_pct)}%</strong> (publicado {formatNumber(row.published_valid_mean_pct)}%, votos válidos)
          {/each}
        </p>
        <p class="small muted">{scenario.out_of_sample.plain}</p>
        <a href="/cenario-corrigido" data-route>Ver o cenário completo e o teste fora da amostra</a>
      </aside>
    {/if}
  </section>
{/if}
