/**
 * Shared, URL-backed state for every interactive chart.
 *
 * Two rules drive this module:
 *
 * 1. A control that does not change what you see is a lie. Window selection is
 *    applied to one canonical date per poll (`field_end`, falling back to
 *    `published_at`), and the *same* filtered set feeds the title, the count,
 *    the axis domain, the table and the explanatory copy.
 * 2. When two windows legitimately contain the same polls, we say so instead of
 *    faking a change.
 */

export type PeriodId = '7' | '30' | 'campaign';
export type ChartKind = 'bars' | 'lines';

export interface PeriodOption {
  id: PeriodId;
  label: string;
  full: string;
}

export const PERIODS: PeriodOption[] = [
  { id: '7', label: '7D', full: 'Últimos 7 dias' },
  { id: '30', label: '30D', full: 'Últimos 30 dias' },
  { id: 'campaign', label: 'Campanha', full: 'Campanha inteira' },
];

/**
 * The date a poll is placed on. Field end is the moment the measurement stopped
 * being taken, which is what a time window should be about; publication date is
 * only a fallback for sources that never disclosed the field period.
 */
export interface DatedPoll {
  field_end?: string | null;
  published_at: string;
}

export const REFERENCE_DATE_LABEL =
  'fim de campo (data de publicação quando o período de campo não foi divulgado)';

export function referenceDate(poll: DatedPoll): string {
  return (poll.field_end || poll.published_at).slice(0, 10);
}

function toTime(value: string): number {
  return new Date(`${value.slice(0, 10)}T12:00:00`).getTime();
}

export function daysBetween(from: string, to: string): number {
  return Math.round((toTime(to) - toTime(from)) / 86_400_000);
}

export interface WindowResult<T> {
  polls: T[];
  /** Inclusive bounds of the polls actually shown, not of the nominal window. */
  from: string | null;
  to: string | null;
  /** The nominal cut-off date the window asked for, for honest labelling. */
  boundary: string | null;
  spanDays: number | null;
  empty: boolean;
}

/**
 * Anchor the window on the most recent measurement rather than on "today", so
 * a stale feed still shows its own last days instead of silently emptying.
 */
export function applyWindow<T extends DatedPoll>(polls: T[], period: PeriodId): WindowResult<T> {
  const sorted = [...polls].sort((a, b) => referenceDate(a).localeCompare(referenceDate(b)));
  if (sorted.length === 0) {
    return { polls: [], from: null, to: null, boundary: null, spanDays: null, empty: true };
  }
  const latest = referenceDate(sorted[sorted.length - 1]);
  let selected = sorted;
  let boundary: string | null = null;
  if (period !== 'campaign') {
    const limit = Number(period);
    selected = sorted.filter((poll) => daysBetween(referenceDate(poll), latest) <= limit);
    const boundaryTime = toTime(latest) - limit * 86_400_000;
    boundary = new Date(boundaryTime).toISOString().slice(0, 10);
  }
  if (selected.length === 0) {
    return { polls: [], from: null, to: null, boundary, spanDays: null, empty: true };
  }
  const from = referenceDate(selected[0]);
  const to = referenceDate(selected[selected.length - 1]);
  return { polls: selected, from, to, boundary, spanDays: daysBetween(from, to), empty: false };
}

/**
 * Which other periods select exactly the same polls. Used to tell the reader
 * "the same 2 polls are in both windows" instead of pretending the control did
 * something.
 */
export function equivalentPeriods<T extends DatedPoll>(
  polls: T[],
  period: PeriodId,
  identity: (poll: T) => string,
): PeriodId[] {
  const key = (list: T[]) => list.map(identity).sort().join('|');
  const current = key(applyWindow(polls, period).polls);
  return PERIODS.filter((option) => option.id !== period)
    .filter((option) => key(applyWindow(polls, option.id).polls) === current)
    .map((option) => option.id);
}

export function periodLabel(period: PeriodId): string {
  return PERIODS.find((option) => option.id === period)?.full ?? 'Período';
}

/* ------------------------------------------------------------------ *
 * URL synchronisation: deep links and browser back/forward must work.
 * ------------------------------------------------------------------ */

export interface ChartQuery {
  periodo?: PeriodId;
  grafico?: ChartKind;
  series?: string[];
}

function isPeriod(value: string | null): value is PeriodId {
  return value === '7' || value === '30' || value === 'campaign';
}

function isKind(value: string | null): value is ChartKind {
  return value === 'bars' || value === 'lines';
}

export function readChartQuery(search: string, prefix = ''): ChartQuery {
  const params = new URLSearchParams(search);
  const period = params.get(`${prefix}periodo`);
  const kind = params.get(`${prefix}grafico`);
  const series = params.get(`${prefix}series`);
  return {
    periodo: isPeriod(period) ? period : undefined,
    grafico: isKind(kind) ? kind : undefined,
    series: series ? series.split(',').filter(Boolean) : undefined,
  };
}

/**
 * Replace (not push) while the user is toggling, so back/forward steps through
 * meaningful navigation instead of every chip click — but push when the window
 * changes, because that is the state a deep link is expected to restore.
 */
export function writeChartQuery(query: ChartQuery, prefix = '', mode: 'push' | 'replace' = 'replace'): void {
  if (typeof window === 'undefined') return;
  const url = new URL(window.location.href);
  const set = (name: string, value: string | undefined) => {
    if (value === undefined || value === '') url.searchParams.delete(`${prefix}${name}`);
    else url.searchParams.set(`${prefix}${name}`, value);
  };
  set('periodo', query.periodo);
  set('grafico', query.grafico);
  set('series', query.series?.length ? query.series.join(',') : undefined);
  const next = `${url.pathname}${url.search}${url.hash}`;
  const current = `${window.location.pathname}${window.location.search}${window.location.hash}`;
  if (next === current) return;
  if (mode === 'push') window.history.pushState({}, '', next);
  else window.history.replaceState({}, '', next);
}

/* ------------------------------------------------------------------ *
 * Scale helpers. Vote-share bars always start at zero.
 * ------------------------------------------------------------------ */

export interface Scale {
  min: number;
  max: number;
  ticks: number[];
  zeroBased: boolean;
}

export function shareScale(values: number[], { zoom = false }: { zoom?: boolean } = {}): Scale {
  const highest = values.length ? Math.max(...values) : 0;
  if (!zoom) {
    const max = Math.max(10, Math.ceil((highest + 2) / 10) * 10);
    const step = max / 4;
    return { min: 0, max, ticks: [0, step, step * 2, step * 3, max], zeroBased: true };
  }
  const lowest = values.length ? Math.min(...values) : 0;
  const pad = Math.max(1, (highest - lowest) * 0.15);
  const min = Math.max(0, Math.floor((lowest - pad) / 5) * 5);
  const max = Math.ceil((highest + pad) / 5) * 5;
  const step = (max - min) / 4;
  return {
    min,
    max,
    ticks: [min, min + step, min + step * 2, min + step * 3, max],
    zeroBased: min === 0,
  };
}

/** Symmetric scale for signed error charts, so zero sits in the middle. */
export function signedScale(values: number[]): Scale {
  const bound = Math.max(1, ...values.map((value) => Math.abs(value)));
  const max = Math.ceil(bound / 2) * 2;
  return { min: -max, max, ticks: [-max, -max / 2, 0, max / 2, max], zeroBased: false };
}
